export const initials = (name = '') => name.split(' ').map(word => word[0]).slice(0, 2).join('').toUpperCase();
export const titleCase = (value = '') => value.replaceAll('_', ' ').replace(/\b\w/g, char => char.toUpperCase());
export const dateLabel = value => value ? new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'No deadline';
export const relativeTime = value => {
  if (!value) return 'Just now';
  const minutes = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 60000));
  if (minutes < 1) return 'Just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (minutes < 1440) return `${Math.floor(minutes / 60)}h ago`;
  return `${Math.floor(minutes / 1440)}d ago`;
};
export const localDateInput = value => value ? String(value).slice(0, 10) : '';
export const coverFor = project => project?.cover || project?.cover_image || '/assets/botanica.svg';
export const statusLabel = status => ({ in_review: 'In review', changes_requested: 'Changes requested', approved: 'Approved', draft: 'Draft', active: 'Active', archived: 'Archived', completed: 'Completed' }[status] || titleCase(status));

import { initials, statusLabel } from '../utils/format';
import Icon from './Icon';

export function Avatar({ user, name, size = '', color = '' }) {
  const label = user?.name || user?.full_name || name || 'Team member';
  return <span className={`avatar ${size} ${color || user?.color || ''}`} title={label}>{initials(label)}</span>;
}
export function AvatarStack({ users = [], limit = 3 }) {
  return <div className="avatar-stack">{users.slice(0, limit).map((user, index) => <Avatar key={user.id || index} user={user} size="small" color={['peach', 'lavender', 'mint'][index % 3]} />)}{users.length > limit && <span className="avatar small extra">+{users.length - limit}</span>}</div>;
}
export function Badge({ status, children }) {
  return <span className={`badge ${status || ''}`}><span className="status-dot" />{children || statusLabel(status)}</span>;
}
export function EmptyState({ title = 'Nothing here yet', children, action }) {
  return <div className="empty-state"><span className="empty-icon"><Icon name="layers" size={26} /></span><h3>{title}</h3>{children && <p>{children}</p>}{action}</div>;
}
export function LoadingState({ label = 'Loading your workspace…' }) {
  return <div className="loading-state" role="status"><span className="spinner" /><p>{label}</p></div>;
}
export function ErrorState({ error, retry }) {
  return <div className="error-state" role="alert"><Icon name="help" /><div><strong>Something needs a second look</strong><p>{error?.message || String(error)}</p></div>{retry && <button className="button secondary" onClick={retry}>Try again</button>}</div>;
}
export function SectionHeading({ title, subtitle, action }) {
  return <div className="section-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>;
}
export function FormField({ label, children, hint }) {
  return <label className="form-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>;
}

import { useEffect, useRef } from 'react';
import Icon from './Icon';

export default function Modal({ title, subtitle, children, onClose, wide = false }) {
  const dialog = useRef(null);
  useEffect(() => {
    const node = dialog.current;
    const previous = document.activeElement;
    node.showModal();
    return () => { node.close(); previous?.focus?.(); };
  }, []);
  return <dialog ref={dialog} className={`modal ${wide ? 'wide' : ''}`} onCancel={event => { event.preventDefault(); onClose(); }} onClick={event => { if (event.target === event.currentTarget) onClose(); }} aria-labelledby="modal-title">
    <div className="modal-header"><div><h2 id="modal-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" aria-label="Close dialog" onClick={onClose}><Icon name="close" /></button></div>
    {children}
  </dialog>;
}

