  return `/assets/${name.includes('botan') ? 'botanica' : name.includes('studio') ? 'studio' : name.includes('field') ? 'fieldnotes' : 'forma'}.svg`;
}
export default function ProjectCard({ project, people = [], onOpen }) {
  const total = project.assetCount || 0;
  const approved = project.approvedCount || 0;
  const progress = total ? Math.round(approved / total * 100) : 0;
  const members = people.filter(person => project.memberIds?.includes(person.id));
  return <button className="project-card" onClick={() => onOpen(project.id)}><div className="project-cover"><img src={projectCover(project)} alt={`${project.name} project cover`} loading="lazy" /><span className="project-cover-tag">{project.archived ? 'Archived' : 'In progress'}</span></div><div className="project-card-body"><div className="project-card-title"><h3>{project.name}</h3><Icon name="arrow" size={17} /></div><p>{project.description || 'A little clarity for your next big idea.'}</p><div className="project-progress-label"><span>{approved} of {total} assets approved</span><strong>{progress}%</strong></div><div className="progress-track"><span style={{ width: `${progress}%`, background: project.color || '#8b76ae' }} /></div><div className="project-card-footer"><AvatarStack users={members} /><span><Icon name="layers" size={14} /> {total} assets</span></div></div></button>;
}

import Icon from '../../shared/components/Icon';
import { Avatar, Badge, EmptyState } from '../../shared/components/Primitives';
import { dateLabel } from '../../shared/utils/format';

export default function AssetTable({ assets = [], onOpen, people = [], compact = false }) {
  if (!assets.length) return <EmptyState title="A clear desk. A fresh start.">No assets match this view. Try another filter or create your first asset.</EmptyState>;
  return <div className="asset-table-wrap"><table className={`asset-table ${compact ? 'compact' : ''}`}><thead><tr><th>ASSET NAME</th><th>STATUS</th>{!compact && <th>REVIEWERS</th>}<th>DUE DATE</th><th aria-label="Open asset" /></tr></thead><tbody>{assets.map(asset => {
    const reviewers = people.filter(person => asset.reviewerIds?.includes(person.id));
    const overdue = asset.dueAt && new Date(asset.dueAt).getTime() < Date.now() && asset.status !== 'approved';
    return <tr key={asset.id}><td><button className="asset-name-button" onClick={() => onOpen(asset.id)}><span className={`asset-thumb ${asset.type === 'copy' ? 'copy-thumb' : ''}`}>{asset.thumbnail ? <img src={asset.thumbnail} alt="" loading="lazy" /> : <Icon name={asset.type === 'image' ? 'image' : 'file'} size={22} />}</span><span><strong>{asset.title}</strong><small>{asset.projectName} <span>·</span> v{asset.version || 1}</small></span></button></td><td><Badge status={asset.status} /></td>{!compact && <td><div className="avatar-stack">{reviewers.slice(0, 3).map((person, index) => <Avatar key={person.id} user={person} size="small" color={['peach', 'lavender', 'mint'][index]} />)}{!reviewers.length && <span className="muted">Unassigned</span>}</div></td>}<td><span className={`due-date ${overdue ? 'overdue' : ''}`}><Icon name="clock" size={14} />{dateLabel(asset.dueAt)}</span></td><td><button className="icon-button" aria-label={`Review ${asset.title}`} onClick={() => onOpen(asset.id)}><Icon name="chevron" size={17} /></button></td></tr>;
  })}</tbody></table></div>;
}

import useResource from '../../shared/api/useResource';
import Icon from '../../shared/components/Icon';
import { Avatar, ErrorState, LoadingState, SectionHeading, EmptyState } from '../../shared/components/Primitives';
import { relativeTime, dateLabel } from '../../shared/utils/format';
import ProjectCard from '../projects/ProjectCard';
import AssetTable from '../assets/AssetTable';

export default function Dashboard({ user, projects, people, navigate, onCreate, refreshKey }) {
  const reports = useResource('/reports', null, refreshKey);
  const assets = useResource('/assets?pageSize=100&sort=due', null, refreshKey);
  const activity = useResource('/activity', [], refreshKey);
  if (reports.loading || assets.loading) return <LoadingState />;
  if (reports.error || assets.error) return <ErrorState error={reports.error || assets.error} retry={() => { reports.refresh(); assets.refresh(); }} />;
  const summary = reports.data?.summary || {};
  const items = assets.data?.items || [];
  const reviewQueue = items.filter(asset => ['in_review', 'changes_requested'].includes(asset.status)).slice(0, 4);
  const deadlines = items.filter(asset => asset.dueAt && asset.status !== 'approved').sort((first, second) => new Date(first.dueAt).getTime() - new Date(second.dueAt).getTime()).slice(0, 3);
  const stats = [
    ['folder', 'Active projects', projects.filter(project => !project.archived).length, 'Good things in motion', 'violet'],
    ['review', 'Awaiting review', summary.inReview || 0, 'Ready for a fresh pair of eyes', 'amber'],
    ['check', 'Approved assets', summary.approved || 0, 'One step closer to out there', 'green'],
    ['clock', 'Overdue reviews', summary.overdue || 0, 'A gentle nudge might help', 'rose'],
  ];
  return <><div className="page-heading"><div><p className="eyebrow">YOUR WORK, IN A GOOD PLACE</p><h1>Let’s make good things happen<span className="heading-star">✳</span></h1><p>Welcome back, {user.name.split(' ')[0]}. Here’s what’s moving in your workspace.</p></div>{user.role !== 'reviewer' && <button className="button primary" onClick={onCreate}><Icon name="plus" size={18} />New project</button>}</div>
    <div className="dashboard-stats">{stats.map(([icon, label, value, description, color]) => <button key={label} className="stat-card" onClick={() => navigate(label === 'Active projects' ? 'projects' : `assets${label === 'Awaiting review' ? '?status=in_review' : label === 'Approved assets' ? '?status=approved' : '?overdue=true'}`)}><div className="stat-label"><span>{label}</span><span className={`stat-icon ${color}`}><Icon name={icon} size={18} /></span></div><strong>{value}</strong><small>{description}</small></button>)}</div>
    <section className="projects-section"><SectionHeading title="Projects in motion" subtitle="A little progress, every day." action={<button className="text-button" onClick={() => navigate('projects')}>All projects<Icon name="arrow" size={15} /></button>} /><div className="project-grid dashboard-projects">{projects.filter(project => !project.archived).slice(0, 3).map(project => <ProjectCard key={project.id} project={project} people={people} onOpen={id => navigate(`project/${id}`)} />)}</div>{!projects.length && <EmptyState title="Make room for your first project." action={<button className="button primary" onClick={onCreate}>New project</button>} />}</section>
    <div className="dashboard-bottom"><section className="panel review-panel"><SectionHeading title="Ready for a closer look" subtitle="These assets could use your thoughtful feedback." action={<button className="text-button" onClick={() => navigate('reviews')}>View all<Icon name="arrow" size={15} /></button>} /><AssetTable assets={reviewQueue} people={people} onOpen={id => navigate(`asset/${id}`)} compact /></section><section className="panel deadlines-panel"><SectionHeading title="Coming up" action={<span className="subtle-icon"><Icon name="clock" size={18} /></span>} /><div className="deadline-list">{deadlines.map(asset => <button className="deadline-item" key={asset.id} onClick={() => navigate(`asset/${asset.id}`)}><span className={`date-block ${new Date(asset.dueAt).getTime() < Date.now() ? 'late' : ''}`}><small>{new Date(asset.dueAt).toLocaleDateString('en-US', { month: 'short' }).toUpperCase()}</small><strong>{new Date(asset.dueAt).getDate()}</strong></span><span><strong>{asset.title}</strong><small>{asset.projectName}</small></span><Icon name="chevron" size={15} /></button>)}{!deadlines.length && <p className="muted">All caught up. Enjoy a little breathing room.</p>}</div><div className="deadline-note"><span>✳</span><p>A clear deadline makes<br />room for better work.</p></div></section></div>
    <section className="activity-section"><SectionHeading title="Around the room" subtitle="The small steps behind the big ideas." /><div className="activity-strip">{activity.data?.slice(0, 3).map(event => <button className="activity-item" key={event.id} onClick={() => event.assetId && navigate(`asset/${event.assetId}`)}><Avatar user={event.actor} color="lavender" size="small" /><div><p><strong>{event.actor?.name || 'A teammate'}</strong> {event.description || event.action.replaceAll('_', ' ')}</p><small>{relativeTime(event.createdAt)}{event.assetTitle && ` · ${event.assetTitle}`}</small></div></button>)}{!activity.data?.length && <p className="muted">Your workspace activity will appear here.</p>}</div></section>
  </>;
}

