import Icon from './Icon';

const steps = [
  ['folder', 'Make a little room', 'Create a project and choose the people who should have access. Keep one campaign or body of work together.'],
  ['file', 'Start with a draft', 'Create a copy document or choose a bundled visual. Add a deadline, reviewers, and one or more ordered approval stages.'],
  ['review', 'Bring fresh eyes in', 'Send the exact draft for review. Assigned reviewers can approve or request changes. Authors cannot approve their own work.'],
  ['message', 'Keep feedback in context', 'Select text or click a point on an image to anchor a comment. Reply, resolve, and keep the conversation connected to its version.'],
  ['layers', 'Make the next version better', 'Create a revised version when content changes. Old feedback and decisions remain in history; the new version begins a fresh review.'],
  ['download', 'Wrap up with confidence', 'Once every stage is approved, export the approved content manifest. Check Reports for progress and reviewer workload.'],
];
export default function Guide() {
  return <><div className="page-heading"><div><p className="eyebrow">A LITTLE ORIENTATION</p><h1>You’re in the right room<span className="heading-star">✳</span></h1><p>A thoughtful workflow. A clearer path from draft to done.</p></div></div><div className="guide-grid">{steps.map(([icon, title, body], index) => <section className="panel guide-card" key={title}><span className="guide-step">0{index + 1}<Icon name={icon} size={22} /></span><h2>{title}</h2><p>{body}</p></section>)}</div><div className="guide-permissions"><strong>Everyone has their part to play.</strong><p>Owners manage the workspace. Editors create and revise work. Reviewers give feedback and record decisions on assigned review stages. Access is checked on every request.</p></div></>;
}

import { download } from '../../shared/api/client';
import useResource from '../../shared/api/useResource';
import Icon from '../../shared/components/Icon';
import { Avatar, ErrorState, LoadingState, SectionHeading } from '../../shared/components/Primitives';
import { dateLabel } from '../../shared/utils/format';

export default function Reports({ navigate, refreshKey, notify }) {
  const resource = useResource('/reports', null, refreshKey);
  if (resource.loading) return <LoadingState label="Putting the progress in perspective…" />;
  if (resource.error) return <ErrorState error={resource.error} retry={resource.refresh} />;
  const { summary, byProject = [], workload = [], trend = [] } = resource.data;
  const maxTrend = Math.max(1, ...trend.map(day => day.approvals));
  async function exportReport() { try { await download('/reports/export.csv', 'reviewroom-workspace-report.csv'); notify('Your workspace report is ready.'); } catch (error) { notify(error.message, 'error'); } }
  return <><div className="page-heading"><div><p className="eyebrow">THE BIGGER PICTURE</p><h1>Good work adds up<span className="heading-star">✳</span></h1><p>A clear view of your progress, your process, and your people.</p></div><button className="button secondary" onClick={exportReport}><Icon name="download" size={17} />Export report</button></div><div className="dashboard-stats report-stats">{[['Total assets', summary.totalAssets, 'Every piece of the work'], ['Approval rate', `${summary.approvalRate}%`, 'Assets with every stage approved'], ['Average review cycle', `${summary.averageCycleHours}h`, 'Submission to final approval'], ['Awaiting review', summary.inReview, `${summary.overdue} overdue reviews`]].map(([label, value, description]) => <div className="stat-card" key={label}><div className="stat-label">{label}<Icon name="chart" size={16} /></div><strong>{value}</strong><small>{description}</small></div>)}</div><div className="reports-grid"><section className="panel report-projects"><SectionHeading title="Progress by project" subtitle="Small steps toward a shared finish line." /><div className="project-report-list">{byProject.map(project => <button key={project.id} onClick={() => navigate(`project/${project.id}`)}><div><strong>{project.name}</strong><span>{project.approved} / {project.total} approved</span></div><div className="progress-track"><span style={{ width: `${project.total ? project.approved / project.total * 100 : 0}%`, background: project.color }} /></div><small>{project.inReview} in review <span>·</span> {project.overdue} overdue</small></button>)}</div></section><section className="panel report-trend"><SectionHeading title="A week of forward motion" subtitle="Recorded approvals over the last 7 days." /><div className="trend-chart" role="img" aria-label={`Daily approvals: ${trend.map(day => `${dateLabel(day.date)}, ${day.approvals}`).join('; ')}`}>{trend.map(day => <div className="trend-column" key={day.date}><strong>{day.approvals}</strong><div className="trend-bar-track"><span style={{ height: `${Math.max(3, day.approvals / maxTrend * 100)}%` }} /></div><small>{new Date(`${day.date}T12:00:00`).toLocaleDateString('en-US', { weekday: 'short' })}</small></div>)}</div><p className="chart-note">Every yes moves a good idea forward.</p></section></div><section className="panel workload-panel"><SectionHeading title="The people behind the progress" subtitle="Current stage assignments that are still waiting for a decision." /><div className="workload-grid">{workload.map(item => <div className="workload-card" key={item.reviewer.id}><Avatar user={item.reviewer} color="lavender" /><div><strong>{item.reviewer.name}</strong><small>{item.reviewer.role}</small></div><span><strong>{item.assigned}</strong><small>assigned</small></span><span className={item.overdue ? 'overdue' : 'muted'}>{item.overdue} overdue</span></div>)}</div></section></>;
}

import { useCallback, useEffect, useState } from 'react';
import { api, setToken, setUnauthorizedHandler } from './shared/api/client';
import useResource from './shared/api/useResource';
import Shell from './shared/components/Shell';
import Icon from './shared/components/Icon';
import { ErrorState, LoadingState } from './shared/components/Primitives';
import Guide from './shared/components/Guide';
import Login from './features/auth/Login';
import Dashboard from './features/dashboard/Dashboard';
import Projects from './features/projects/Projects';
import ProjectDetail from './features/projects/ProjectDetail';
import ProjectForm from './features/projects/ProjectForm';
import Assets from './features/assets/Assets';
import AssetDetail from './features/assets/AssetDetail';
import AssetForm from './features/assets/AssetForm';
import Inbox from './features/inbox/Inbox';
import Reports from './features/reports/Reports';

function readRoute() { return window.location.hash.slice(1) || 'overview'; }
export default function App() {
  const [user, setUser] = useState(null);
  const [booting, setBooting] = useState(true);
  const [route, setRoute] = useState(readRoute);
  const [search, setSearch] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState(null);
  const [routePath, query = ''] = route.split('?');
  const [page, id] = routePath.split('/');
  const projects = useResource(user ? '/projects' : null, [], refreshKey);
  const people = useResource(user ? '/people' : null, [], refreshKey);
  const inbox = useResource(user ? '/inbox' : null, [], refreshKey);
  const changed = useCallback(() => setRefreshKey(value => value + 1), []);
  const notify = useCallback((message, type = 'success') => setToast({ message, type }), []);
  const navigate = useCallback(path => { window.location.hash = path; setRoute(path); window.scrollTo({ top: 0, behavior: 'instant' }); }, []);
  useEffect(() => {
    const handleRoute = () => setRoute(readRoute());
    window.addEventListener('hashchange', handleRoute);
    setUnauthorizedHandler(() => { setUser(null); setModal(null); });
    const controller = new AbortController();
    api('/auth/me', { signal: controller.signal }).then(setUser).catch(error => { if (error.name !== 'AbortError' && error.status !== 401) notify('The workspace could not connect. Sign in to try again.', 'error'); }).finally(() => { if (!controller.signal.aborted) setBooting(false); });
    return () => { controller.abort(); window.removeEventListener('hashchange', handleRoute); };
  }, [notify]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(null), 5500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { document.title = `${({ overview: 'Overview', projects: 'Projects', assets: 'All assets', reviews: 'My reviews', reports: 'Reports', inbox: 'Inbox', asset: 'Asset review', project: 'Project', help: 'Workspace guide' })[page] || 'Workspace'} · Reviewroom`; }, [page]);
  async function logout() { try { await api('/auth/logout', { method: 'POST' }); } catch { /* Clear the browser session even when the server is unavailable. */ } finally { setToken(''); setUser(null); setModal(null); setSearch(''); navigate('overview'); } }
  const createAsset = projectId => { if (!projects.data?.some(project => !project.archived)) { notify('Create an active project first. Every good idea needs a home.'); setModal({ type: 'project' }); } else setModal({ type: 'asset', projectId }); };
  if (booting) return <LoadingState label="Making a little room for your work…" />;
  if (!user) return <><Login onLogin={value => { setUser(value); changed(); navigate('overview'); }} />{toast && <div className={`toast ${toast.type}`} role="status">{toast.message}</div>}</>;
  const common = { user, people: people.data || [], projects: projects.data || [], navigate, refreshKey, notify };
  let content;
  if (projects.loading || people.loading) content = <LoadingState />;
  else if (projects.error || people.error) content = <ErrorState error={projects.error || people.error} retry={() => { projects.refresh(); people.refresh(); }} />;
  else if (page === 'overview') content = <Dashboard {...common} onCreate={() => setModal({ type: 'project' })} />;
  else if (page === 'projects') content = <Projects {...common} onCreate={() => setModal({ type: 'project' })} />;
  else if (page === 'project') content = <ProjectDetail {...common} key={id} id={id} onCreate={createAsset} onChanged={changed} />;
  else if (page === 'assets' || page === 'reviews') content = <Assets {...common} key={page} search={search} query={query} reviews={page === 'reviews'} onCreate={() => createAsset('')} />;
  else if (page === 'asset') content = <AssetDetail {...common} key={id} id={id} onChanged={changed} />;
  else if (page === 'inbox') content = inbox.error ? <ErrorState error={inbox.error} retry={inbox.refresh} /> : <Inbox {...common} items={inbox.data || []} onChanged={changed} />;
  else if (page === 'reports') content = <Reports {...common} />;
  else content = <Guide />;
  return <><Shell user={user} page={page} navigate={navigate} unread={inbox.data?.filter(item => !item.read).length || 0} search={search} setSearch={setSearch} onLogout={logout}>{content}</Shell>{modal?.type === 'project' && <ProjectForm people={people.data || []} user={user} onClose={() => setModal(null)} onSaved={project => { setModal(null); changed(); navigate(`project/${project.id}`); notify('A new room for good work. Your project is ready.'); }} />}{modal?.type === 'asset' && <AssetForm projects={projects.data || []} projectId={modal.projectId} people={people.data || []} user={user} onClose={() => setModal(null)} onSaved={asset => { setModal(null); changed(); navigate(`asset/${asset.id}`); notify('Your first draft is in. Let’s make it a good one.'); }} />}{toast && <div className={`toast ${toast.type}`} role="status"><Icon name={toast.type === 'error' ? 'help' : 'check'} size={18} /><span>{toast.message}</span><button className="icon-button" aria-label="Dismiss notification" onClick={() => setToast(null)}><Icon name="close" size={15} /></button></div>}</>;
}

