/* Reviewroom: quiet surfaces, clear hierarchy, and a little character. */
:root{font-family:Roboto,Arial,sans-serif;color:#35313c;background:#f8f7f4;font-synthesis:none;font-weight:400;font-size:14px;line-height:1.5;--ink:#34303d;--muted:#89848d;--purple:#7964a4;--purple-deep:#66518f;--border:#eae7e3;--surface:#fff;--sidebar:#292636}
